  ('999bb4cc-755a-516b-9aef-fc402257f812', 'history-2014-06-15-e5212f4b96ec269b', '爱上邓丽君', '音乐剧', '2014-06-15T12:00:00+08:00', '2014-08-31T12:00:00+08:00', '8ebf6fba-1172-53a9-b474-4743f48d340f', '北京', '中国', 39.92882, 116.42665, '2014修排版在北京东方剧院驻演78天、50场。郑云龙确认饰演男主角周梦君；旧页面未完整保留逐日个人卡司，按确认参演演期记录。', 'https://news.sina.com.cn/c/2014-06-20/210630397956.shtml', 'published', '{"import_source":"event-earth-demo","import_version":1,"legacy_ids":["zhengyunlong-2014-c015fb4425"],"artists":["zyl"],"roles":{"zyl":"周梦君"},"duties":{"zyl":"主演"},"date_labels":["2014-06-15—2014-08-31 演期内50场；公开报道可核首演场19:30"],"tour_batches":["2014修排版·北京驻演"],"tour_summaries":["以邓丽君经典歌曲串联原创故事：迷茫的年轻音乐人周梦君在“邓丽君”的帮助下走出感情与创作困境，在现实与回忆交错中重新理解爱与生活。"],"source_urls":["https://news.sina.com.cn/c/2014-06-20/210630397956.shtml","https://zh.wikipedia.org/wiki/%E9%83%91%E4%BA%91%E9%BE%99"],"media_urls":["https://www.youtube.com/playlist?list=PLYQCfqkcZ1LU-ywEdyNV2OtEfJoiH7Aa2"],"sessions":[{"person_id":"zyl","sessions":[{"date":"2014-06-15","endDate":"2014-08-31","dateLabel":"2014-06-15—2014-08-31","time":"演期内50场；公开报道可核首演场19:30"}]}]}'::jsonb),
